"""The data files at a glance, for people: capri_data/MANIFEST.json (generated, do not edit).

One entry per data file under capri_data that the declarations know: every declared CSV (capri_data/schema/*.sql)
and the catalogue's other files (05_file_catalogue.sql: JSON files, a compressed CSV, a folder). Each entry says what
the file holds and where it comes from, without SQL:

  description     the table's comment (what the file holds and its builder)
  vintage, domain, status, vintage_exception
                  from the files' catalogue, where the file has a row there
  rows, columns   counted in the file now (CSV: data lines and header fields; JSON and folders: left out)
  units           the units declared for its values (value_units), joined ('to be established' where open)
  read_by_model   the model's modules that name the file (schema.json's static scan)
  origin          its provenance: nature and builder (01_provenance.sql)
  notes           the checked notes on it (02_provenance_notes.sql), with the date checked
  catalogue_note  the catalogue's note (MANIFEST.json's text before 31 October 2026, not re-checked), where there is one

The declarations stay the source: this file is rebuilt from them and from the files (until 31 October 2026 it was kept
by hand, and went stale; tools/check/make_schema_json.py writes the full catalogue for programs, schema.json).

    python tools/check/make_manifest_json.py           # writes capri_data/MANIFEST.json
    python tools/check/make_manifest_json.py --check   # exit 1 if it is not up to date (the test)
"""
from __future__ import annotations

import argparse
import csv
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / "capri_data" / "MANIFEST.json"
sys.path.insert(0, str(Path(__file__).resolve().parent))
import make_schema_json as MS  # noqa: E402
import validate_data as V  # noqa: E402


def _shape(path: Path):
    """(rows, columns) of a CSV file: its data lines and its header's fields."""
    with open(path, newline="", encoding="utf-8") as fh:
        r = csv.reader(fh)
        header = next(r, [])
        n = sum(1 for _ in r)
    return n, len(header)


def build(root: Path = ROOT) -> dict:
    import duckdb
    schema = MS.build(root)
    con = duckdb.connect()
    V.validate(root, verbose=False, con=con, declarations_only=True)
    cat = {r[0]: dict(zip(("vintage", "domain", "status", "units", "vintage_exception", "note"), r[1:]))
           for r in con.execute("SELECT file, vintage, domain, status, units, vintage_exception, note "
                                "FROM file_catalogue").fetchall()}
    files = {}
    for t in schema["tables"].values():
        f = t["file"]
        e = {"description": t.get("comment") or ""}
        c = cat.get(f) or {}
        e.update({k: c[k] for k in ("vintage", "domain", "status", "vintage_exception") if c.get(k)})
        p = Path(root) / f
        if p.exists():
            e["rows"], e["columns"] = _shape(p)
        units = sorted({u["unit"] for u in t.get("units") or [] if u.get("unit")})
        if units:
            e["units"] = ", ".join(units)
        elif t.get("units"):
            e["units"] = "to be established (value_units: open)"
        rb = (t.get("read_by") or {}).get("model")
        if rb:
            e["read_by_model"] = rb
        prov = t.get("provenance") or {}
        if prov:
            e["origin"] = {k: prov[k] for k in ("nature", "builder") if prov.get(k)}
        if t.get("notes"):
            e["notes"] = [f"{n['note']} (checked {n['checked']})" for n in t["notes"]]
        if c.get("note"):
            e["catalogue_note"] = c["note"] + " (not re-checked)"
        files[f] = e
    for f, c in cat.items():
        if f in files:
            continue
        e = {k: c[k] for k in ("vintage", "domain", "status", "vintage_exception") if c.get(k)}
        if c.get("units"):
            e["units"] = c["units"] + " (not re-checked)"
        on = schema.get("other_notes", {}).get(f)
        if on:
            e["notes"] = [f"{n['note']} (checked {n['checked']})" for n in on]
        if c.get("note"):
            e["catalogue_note"] = c["note"] + " (not re-checked)"
        files[f] = e
    return {"_about": "The data files at a glance, generated by tools/check/make_manifest_json.py from the declarations "
                      "(capri_data/schema) and the files; do not edit (edit the .sql files and run the script). "
                      "The checks are capri_mod/data/validate_data.py.",
            "files": dict(sorted(files.items()))}


def render(doc) -> str:
    return json.dumps(doc, indent=1, ensure_ascii=False) + "\n"


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--check", action="store_true")
    a = ap.parse_args()
    out = render(build())
    if a.check:
        ok = OUT.exists() and OUT.read_text(encoding="utf-8") == out
        print("up to date" if ok else f"{OUT.relative_to(ROOT)} is not up to date: run tools/check/make_manifest_json.py")
        sys.exit(0 if ok else 1)
    OUT.write_text(out, encoding="utf-8")
    print(f"{len(json.loads(out)['files'])} files -> {OUT.relative_to(ROOT)}")


if __name__ == "__main__":
    main()
